import{_ as o,l as i,o as e,c as l,v as t,p,x as r,d as u,i as n,S as d}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"发布订阅","description":"","frontmatter":{"title":"发布订阅","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pub-sub.md","filePath":"cs/pub-sub.md","lastUpdated":1789023840000}'),b={name:"cs/pub-sub.md"};function c(h,a,B,_,E,m){const s=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="发布订阅" tabindex="-1">发布订阅 <a class="header-anchor" href="#发布订阅" aria-label="Permalink to &quot;发布订阅&quot;">​</a></h1><div class="epigraph"><p>发布者与订阅者解耦：主题、兴趣、时间都可以解耦。排序与投递次数不随「pubsub」这个词附赠。</p><footer>—— 据 Eugster, Felber, Guerraoui and Kermarrec, The Many Faces of Publish/Subscribe, CSUR 2003 整理</footer></div><p>上一课<a href="/cs/kafka-log">Kafka 日志</a>是带持久游标的一种 pub-sub。缺口是<strong>模式本身</strong>：主题、内容过滤、队列组消费。本课按 Eugster 的分类钉解耦轴，不把 Kafka 配置再抄一遍。后课缓存失效常误用 pub-sub 当可靠通知。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>三种解耦：空间（谁发布谁订阅不必相识）、时间（订阅者离线消息是否还在）、同步（发布是否阻塞到处理完）。实现：主题（topic）、内容（属性过滤）、类型。持久 vs 瞬态：ZK watch 瞬态；日志持久。</p><p>缺口：产品说 pub-sub 常默认「每条都送到、且有序」。规格上要分别买：持久日志、分区序、至少一次、消费者组互斥。没有买就只有尽力而为的广播。</p><p><span class="marginnote">CSUR 2003 是分类综述。Isis 的因果/全序广播是更强的通信原语，属于排序轴。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选拓扑：扇出推、订阅者拉、中间 broker。过滤放发布侧还是订阅侧决定带宽。消费者组：同一逻辑订阅争分区，是队列；每组独立位移，是广播。两者都叫订阅，语义反。</p>',9)),(e(),p(d,null,{default:r(()=>[n(s,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20PUB%5B%22%E5%8F%91%E5%B8%83%22%5D%20--%3E%20BR%5B%22%E4%BB%A3%E7%90%86%20%2F%20%E6%97%A5%E5%BF%97%22%5D%0A%20%20BR%20--%3E%20G1%5B%22%E6%B6%88%E8%B4%B9%E7%BB%84%20A%20%E4%BA%89%E5%88%86%E5%8C%BA%22%5D%0A%20%20BR%20--%3E%20G2%5B%22%E6%B6%88%E8%B4%B9%E7%BB%84%20B%20%E7%8B%AC%E7%AB%8B%E9%87%8D%E6%94%BE%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[u(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与 RPC：RPC 是一对一同步请求；pub-sub 是一对多异步。用 pub-sub 模拟 RPC 要补相关 id 与超时，失败模式回到上一课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>丢失：瞬态总线在订阅者重启时丢。重复：重连重放。乱序：多分区、多发布者无协调。缓存失效若用尽最大努力 pub-sub，会永久脏——下一课。</p><p>本课不写 MQTT/AMQP 帧。也不写社交信息流推荐。</p><p>背压：订阅者慢则代理堆积或丢掉。日志用磁盘换时间；内存总线用丢。选错会把发布者拖死或静默丢失效消息。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把所有消息产品对照表写全。后课默认：说到订阅，先问持久、序、组互斥、投递次数。缓存失效下一课说明「通知丢了怎么办」必须另有 TTL 或版本。</p><p>解耦不是保证。保证逐项买。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Pub-sub 解耦空间/时间/同步；序与次数另规格。</li><li>消费组互斥 vs 独立重放是两种语义。</li><li>瞬态 watch ≠ 持久日志。</li><li>出处：Eugster et al., CSUR 2003。</li></ul>',10))])}const P=o(b,[["render",c]]);export{T as __pageData,P as default};
